#include <bits/stdc++.h>
using namespace std;

struct LazySeg {
    int n;
    vector<long long> tree;
    vector<long long> lazy;

    LazySeg(const vector<long long>& values) {
        n = static_cast<int>(values.size());
        tree.assign(4 * max(1, n), 0);
        lazy.assign(4 * max(1, n), 0);
        if (n > 0) {
            build(1, 0, n - 1, values);
        }
    }

    void build(int node, int left, int right, const vector<long long>& values) {
        if (left == right) {
            tree[node] = values[left];
            return;
        }

        int mid = left + (right - left) / 2;
        build(2 * node, left, mid, values);
        build(2 * node + 1, mid + 1, right, values);

        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }

    void apply(int node, int left, int right, long long increment) {
        tree[node] += increment * (right - left + 1);
        lazy[node] += increment;
    }

    void push(int node, int left, int right) {
        if (left == right || lazy[node] == 0) {
            return;
        }

        int mid = left + (right - left) / 2;
        apply(2 * node, left, mid, lazy[node]);
        apply(2 * node + 1, mid + 1, right, lazy[node]);
        lazy[node] = 0;
    }

    void add(int queryLeft, int queryRight, long long increment, int node, int left, int right) {
        if (queryRight < left || right < queryLeft) {
            return;
        }

        if (queryLeft <= left && right <= queryRight) {
            apply(node, left, right, increment);
            return;
        }

        push(node, left, right);
        int mid = left + (right - left) / 2;

        add(queryLeft, queryRight, increment, 2 * node, left, mid);
        add(queryLeft, queryRight, increment, 2 * node + 1, mid + 1, right);

        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }

