#include <bits/stdc++.h>
using namespace std;

bool topological(const vector<vector<int>>& neighbors, vector<int>& order) {
    int n = neighbors.size();
    vector<int> indegree(n, 0);
    queue<int> ready;
    order.clear();

    for (int vertex = 0; vertex < n; vertex++) {
        for (int next : neighbors[vertex]) {
            indegree[next]++;
        }
    }

    for (int vertex = 0; vertex < n; vertex++) {
        if (indegree[vertex] == 0) {
            ready.push(vertex);
        }
    }

    while (!ready.empty()) {
        int vertex = ready.front();
        ready.pop();
        order.push_back(vertex);

        for (int next : neighbors[vertex]) {
            indegree[next]--;

            if (indegree[next] == 0) {
                ready.push(next);
            }
        }
    }

    if (static_cast<int>(order.size()) != n) {
        order.clear();
        return false;
    }

    return true;
}

int main() {
